{
  "verdict": "correction_required",
  "humanApproval": false,
  "findings": [
    {
      "severity": "high",
      "file": "packages/workflow-control/src/featureEvaluation.ts",
      "line": null,
      "location": "OfficialRepairChildPort constructor: mutate; DurableRepairChildBroker.execute",
      "reason": "The new repair-child dispatch guard does not cover the actual effects. dispatchRepairChildMutation invokes the async port inside its writer transaction, but mutate immediately awaits readChild. The transaction ends before createChild executes. It then awaits additional operations before createTaskRefCas, without another authority check. Approval invalidation or lease takeover during either read can therefore permit subsequent Beads/Git mutations. The supplied negative test changes documents before dispatch, so it misses this gap.",
      "proposedFix": "Guard each actual effect separately after its asynchronous observations: reverify documents and check current approval, cancellation and leases at createChild and createTaskRefCas dispatch. Add tests that invalidate approval or replace the owner while readChild/readTaskRef is suspended, and assert zero subsequent effects."
    },
    {
      "severity": "high",
      "file": "packages/workflow-control/src/storage.ts",
      "line": null,
      "location": "importWorkflowLineage",
      "reason": "Import verifies the target run before inserting its lineage_approved_heads row. For a fresh target, verifyBoundary finds no accepted ref and checks the publication directory. If the incoming task worktree has changed normative bytes while publication bytes remain intact, import can still persist the lineage and advance the run to pipeline. The imported-worktree test manually inserts the ledger first and calls the verifier; it does not exercise this admission gap.",
      "proposedFix": "Resolve and verify the incoming request.ref through trusted repository bindings within a durable verification attempt before accepting the import. Bind that verification to the exact import request and recheck authority in the import transaction. Test the public import path with clean publication bytes and changed incoming-worktree documents."
    },
    {
      "severity": "medium",
      "file": "packages/workflow-control/test/documentApproval.test.ts",
      "line": null,
      "location": "Entry-point negative matrix and connected Docker scenarios",
      "reason": "The supplied tests do not establish complete DB-T01–11 coverage. The entry matrices exercise changed bytes against selected storage methods, but not deletion/artifact tampering at every mapped boundary or all composed effect paths. DB-T10 uses coordinator packet creation followed by manually staged/direct Docker consumption; the actual launcher tests separately use synthetic scheduler authorization. Neither demonstrates the complete publication-to-coordinator-launch-to-result-to-restart flow. These gaps allow the two defects above to coexist with green counts.",
      "proposedFix": "Retain an explicit requirement/boundary-to-test inventory, add composed import and per-effect repair tests, and add a connected public coordinator/launcher/restart scenario with tampered spec and verification documents. Mark uncovered required scenarios blocked rather than inferring coverage from positive regression suites."
    }
  ],
  "resolvedPriorFindings": [
    {
      "finding": "Taskless guards ignored accepted task sources",
      "assessment": "Addressed for existing ledgers: taskless verification enumerates accepted refs and checks their registered worktrees."
    },
    {
      "finding": "Imported lineage ignored",
      "assessment": "Existing imported ledger rows are now included. Initial import admission remains defective as reported above."
    },
    {
      "finding": "Credential issue lacked final authority check",
      "assessment": "Addressed in the supplied production path: dispatchSchedulerCredentialIssue checks authority and elapsed-time-adjusted leases under the writer transaction before initiating the credential subprocess."
    },
    {
      "finding": "Unsafe Git errors",
      "assessment": "Document-source Git failures are translated to bounded reason codes, with supplied redaction tests."
    },
    {
      "finding": "Malformed launcher test packet",
      "assessment": "Addressed: supplied launcher fixtures construct typed packets with document bindings."
    },
    {
      "finding": "Provenance/current accepted workspace",
      "assessment": "Repository identity, publication ancestry and existing accepted-worktree resolution are implemented; initial import remains incomplete."
    },
    {
      "finding": "Durable snapshot invalidation",
      "assessment": "Addressed: snapshot checks run within durable attempts, and failed settlement leaves pending authority quarantined."
    },
    {
      "finding": "Exact persisted scheduler packet",
      "assessment": "Addressed: launcher compares the full supplied packet/envelope with persisted scheduler input before staging or issuance."
    },
    {
      "finding": "Conflicting same-status result replay",
      "assessment": "Addressed through deep result comparison and supplied replay tests."
    },
    {
      "finding": "Cleanup after lost approval",
      "assessment": "Addressed for the demonstrated already-attested bootstrap cancellation path; this is not evidence for every interrupted bootstrap state."
    },
    {
      "finding": "Full required negative/runtime/crash coverage",
      "assessment": "Partially addressed. Actual process-death, restored-bytes, competing-process and Docker tests are supplied; exhaustive required coverage remains unproven."
    }
  ],
  "coverageLimits": [
    "Static review of supplied evidence only; no commands executed or state changed.",
    "Line numbers are null because the supplied snippets lack numbered locations; exact symbols identify each finding.",
    "Overlapping source/test digest declarations agree with the manifest where inspected, but content hashes and compiled artifacts were not independently recomputed or verified.",
    "Logs report 790 Linux passes with 15 skips and 58 connected passes. These are retained reports, not independently reproduced results.",
    "DB-T01 lacks explicit assertions for every required digest-changing dimension; DB-T02 does not visibly test unreadable regular files.",
    "DB-T08 migration rollback is tested directly on the schema initializer, rather than a complete historical database upgrade through WorkflowStore.",
    "Hosted checks are explicitly not run; document/link-check results are not supplied.",
    "Owner/critic identities, external adapters and credential service are fixtures. No live managed orchestration qualification is established."
  ],
  "productDecisionsRequired": [],
  "decisionNote": "The findings concern implementation and verification against stated requirements, not unresolved product choices."
}
